-- =============================================================================
-- Fox Hills Residences — dane inwestycji (tabela pages, patrz db/schema.sql)
-- =============================================================================
--
-- Nowa, luksusowa inwestycja KGD na polu golfowym. Szata graficzna wg księgi znaku Fox Hills Residences:
-- logo (public/investments/foxhills/logo-jasne.svg / logo-ciemne.svg), paleta #171A1C / #26292B / #F7F7F7 / #E7E7E7 / #BCC0C1 / #555859,
-- typografia DM Serif Display + Manrope. (slug "/inwestycja/foxhills", szablon "foxhills"
-- — patrz src/components/investments/foxhills/**, rejestr: src/lib/investments/sections.tsx).
--
-- Struktura strony wg oferty: Nawigacja → Hero → O inwestycji → Udogodnienia (features) →
-- Dostępne mieszkania (interaktywny plan zabudowy + lista lokali + prospekt) → Standard wykończenia
-- (3 pakiety) → Galeria → Lokalizacja (opis + odległości) → Mapa interaktywna → Deweloper (KGD) →
-- Kontakt → Stopka. Kontakt i Stopka to globalne komponenty (src/components/shared/*), jak w pozostałych
-- inwestycjach; reszta sekcji jest dedykowana Fox Hills Residences.
--
-- Zdjęcia: wizualizacje z dysku przekonwertowane do WebP i zapisane w public/investments/foxhills/
-- (hero/ — 4 zdjęcia tła, gallery/ — 36 wizualizacji: pełny plik 2200 px + miniatura 900 px).
--
-- ┌─ DANE PRZYKŁADOWE / DO POTWIERDZENIA PRZED PUBLIKACJĄ ───────────────────────────────────────┐
-- │ Brief nie zawierał poniższych informacji — w bazie są wartości WSTAWIONE ROBOCZO, wyraźnie    │
-- │ oznaczone w etykietach pól w panelu admina („DANE PRZYKŁADOWE", „ZWERYFIKUJ"):                │
-- │  • lista budynków i lokali (liczba, metraże, piętra, powierzchnie dodatkowe, STATUSY),         │
-- │    ceny: „Cena na zapytanie" (brak prawdziwych cen — nic nie zostało wymyślone),              │
-- │  • liczby w sekcji „O inwestycji" (6 rezydencji / 12 apartamentów),                            │
-- │  • lokalizacja: środek mapy z linku Google Maps; punkty z OpenStreetMap, czasy dojazdu — szacunek,   │
-- │  • treść standardów wykończenia (Classic / Prestige / Signature) — propozycja do akceptacji,   │
-- │  • link do prospektu informacyjnego i PDF-ów standardów (puste → przyciski „Poproś o …"),      │
-- │  • numer telefonu w nawigacji (z pozostałych inwestycji KGD).                                  │
-- └────────────────────────────────────────────────────────────────────────────────────────────────┘
--
-- UPSERT (ON DUPLICATE KEY UPDATE) — bezpieczne przy ponownym imporcie (uwaga: nadpisuje zmiany z panelu).
--
-- Import: mysql -u UZYTKOWNIK -p NAZWA_BAZY < db/inwestycje/foxhills.sql
-- =============================================================================

INSERT INTO pages (slug, content) VALUES
  ('/inwestycja/foxhills', '{"slug":"/inwestycja/foxhills","parent":null,"template":"foxhills","title":{"value":"Fox Hills Residences | Luksusowe rezydencje na polu golfowym","editable":true,"label":"Tytuł strony","type":"string"},"updatedAt":"2026-10-11","status":"published","nav":{"label":"Fox Hills Residences","order":15},"seo":{"title":{"value":"Fox Hills Residences – luksusowe rezydencje na polu golfowym | KGD Group","editable":true,"label":"Tytuł SEO","type":"string"},"description":{"value":"Fox Hills Residences to ekskluzywne rezydencje na terenie pola golfowego, w otoczeniu lasu sosnowego i jeziora. Apartamenty z prywatnym ogrodem, tarasem z jacuzzi i garażem. Poznaj ofertę KGD Group.","editable":true,"label":"Opis SEO","type":"string"},"keywords":["Fox Hills Residences","Fox Hills","luksusowe rezydencje","apartamenty na polu golfowym","nieruchomości premium Kraków","dom przy polu golfowym","KGD Group","rezydencje z ogrodem i tarasem"],"canonical":"https://kgd-group.pl/inwestycja/foxhills","robots":{"index":true,"follow":true},"author":"KGD Group","ogTitle":"Fox Hills Residences – luksusowe rezydencje na polu golfowym","ogDescription":"Rezydencje z panoramicznymi tarasami i prywatnymi ogrodami, tuż przy polu golfowym. Inwestycja premium KGD Group.","ogImage":"https://kgd-group.pl/investments/foxhills/hero/hero-02.webp","ogType":"website","ogUrl":"https://kgd-group.pl/inwestycja/foxhills","ogSiteName":"KGD Group","ogLocale":"pl_PL","twitterCard":"summary_large_image","twitterTitle":"Fox Hills Residences – luksusowe rezydencje na polu golfowym","twitterDescription":"Rezydencje z panoramicznymi tarasami i prywatnymi ogrodami, tuż przy polu golfowym.","twitterImage":"https://kgd-group.pl/investments/foxhills/hero/hero-02.webp","language":"pl","structuredData":[{"type":"WebPage"}]},"sections":[{"id":"navbar","component":"NavBar","type":"section","label":"Nawigacja","fields":{"menu":{"value":[{"name":"O INWESTYCJI","path":"#o_inwestycji"},{"name":"UDOGODNIENIA","path":"#udogodnienia"},{"name":"APARTAMENTY","path":"#apartamenty"},{"name":"GALERIA","path":"#galeria"},{"name":"LOKALIZACJA","path":"#lokalizacja"},{"name":"DEWELOPER","path":"#deweloper"},{"name":"KONTAKT","path":"#kontakt"}],"editable":true,"label":"Linki nawigacji","type":"table"},"phone":{"value":"12 352 15 00","editable":true,"label":"Telefon","type":"string"},"ctaLabel":{"value":"Umów prezentację","editable":true,"label":"Etykieta przycisku","type":"string"},"ctaHref":{"value":"#kontakt","editable":true,"label":"Adres przycisku","type":"string"}}},{"id":"hero","component":"Hero","type":"section","label":"Hero","fields":{"slides":{"value":[{"image":"/investments/foxhills/hero/hero-01.webp","alt":"Rezydencja Fox Hills Residences o zachodzie słońca nad polem golfowym"},{"image":"/investments/foxhills/hero/hero-02.webp","alt":"Rezydencja Fox Hills Residences o zmierzchu, nad jeziorem"},{"image":"/investments/foxhills/hero/hero-03.webp","alt":"Wieczór nad polem golfowym Fox Hills Residences"},{"image":"/investments/foxhills/hero/hero-04.webp","alt":"Fasada rezydencji Fox Hills Residences w blasku zachodzącego słońca"}],"editable":true,"label":"Zdjęcia w tle (kolumna „image” — upload; kolejność = kolejność slajdów)","type":"table"},"eyebrow":{"value":"Rezydencje na polu golfowym","editable":true,"label":"Nadtytuł","type":"string"},"title":{"value":"Fox Hills Residences","editable":true,"label":"Nazwa inwestycji (logo w hero — tekst alternatywny i nagłówek H1)","type":"string"},"subtitle":{"value":"Miejsce na każdy dzień","editable":true,"label":"Podtytuł (hasło z księgi znaku)","type":"string"},"text":{"value":"Spokojna architektura w naturalnym krajobrazie. Przemyślane detale tworzą miejsce do życia — z panoramicznymi tarasami, prywatnymi ogrodami i widokiem na pole golfowe.","editable":true,"label":"Opis","type":"string"},"primaryLabel":{"value":"Zobacz apartamenty","editable":true,"label":"Przycisk główny — etykieta","type":"string"},"primaryHref":{"value":"#apartamenty","editable":true,"label":"Przycisk główny — adres","type":"string"},"secondaryLabel":{"value":"Umów prezentację","editable":true,"label":"Przycisk dodatkowy — etykieta","type":"string"},"secondaryHref":{"value":"#kontakt","editable":true,"label":"Przycisk dodatkowy — adres","type":"string"},"facts":{"value":[{"icon":"golf","label":"Lokalizacja","value":"Na polu golfowym"},{"icon":"forest","label":"Otoczenie","value":"Las sosnowy i jezioro"},{"icon":"spa","label":"Strefa wypoczynku","value":"Taras z jacuzzi"},{"icon":"garage","label":"Prestiż","value":"Garaż w bryle domu"}],"editable":true,"label":"Pas faktów (ikony: golf, forest, spa, garage, water, glass, garden, light, shield, facade, key, city)","type":"table"}}},{"id":"aboutus","hashId":"o_inwestycji","component":"AboutUs","type":"section","label":"O inwestycji","fields":{"eyebrow":{"value":"O inwestycji","editable":true,"label":"Nadtytuł","type":"string"},"header":{"value":"Fox Hills Residences","editable":true,"label":"Nagłówek","type":"string"},"accent":{"value":"miejsce, w którym czas płynie wolniej","editable":true,"label":"Akcent (kursywa)","type":"string"},"paragraphs":{"value":["Fox Hills Residences to kameralne założenie rezydencjonalne, powstające na terenie pola golfowego. Ciemne fasady o prostej, rzeźbiarskiej bryle spotykają tu ciepło naturalnego drewna, a ogromne przeszklenia otwierają wnętrza na zieleń fairwayów, linię sosnowego lasu i taflę jeziora.","Każda rezydencja zaprojektowana jest tak, by życie toczyło się na zewnątrz równie swobodnie jak w środku: przestronny taras z jacuzzi i strefą wypoczynku, prywatny ogród, garaż z drewnianymi lamelami i wieczorna iluminacja, która nadaje całości charakter prywatnego kurortu.","To adres dla osób, które cenią prywatność, architekturę najwyższej klasy i codzienny kontakt z naturą — bez rezygnowania z bliskości miasta."],"editable":true,"label":"Akapity opisu","type":"table"},"quote":{"value":"Prawdziwy luksus to przestrzeń, cisza i widok, którego nie da się powtórzyć.","editable":true,"label":"Cytat","type":"string"},"imageMain":{"value":"/investments/foxhills/gallery/fasada-ciemna-blacha-i-drewno.webp","editable":true,"label":"Zdjęcie główne","type":"asset"},"imageSecondary":{"value":"/investments/foxhills/gallery/taras-i-jacuzzi-dzien.webp","editable":true,"label":"Zdjęcie dodatkowe","type":"asset"},"stats":{"value":[{"value":"6","label":"Rezydencji"},{"value":"12","label":"Apartamentów"},{"value":"3","label":"Standardy wykończenia"},{"value":"1","label":"Pole golfowe u progu"}],"editable":true,"label":"Liczby (DO POTWIERDZENIA)","type":"table"},"pillars":{"value":[{"icon":"facade","title":"Budynki","text":"Sześć rezydencji o wyrazistej bryle z dwuspadowym dachem, ciemną elewacją i okładziną z drewna. Dwa poziomy, panoramiczne przeszklenia i dachy-tarasy z balustradami ze szkła."},{"icon":"pin","title":"Lokalizacja","text":"Na terenie pola golfowego, w sąsiedztwie lasu sosnowego i jeziora. Spokój i prywatność, a jednocześnie wygodny dojazd do miasta."},{"icon":"spa","title":"Udogodnienia","text":"Taras z jacuzzi, strefa lounge z paleniskiem, prywatny ogród z kameralną iluminacją oraz garaż zintegrowany z bryłą budynku."},{"icon":"key","title":"Najważniejsze cechy","text":"Duże przeszklenia, naturalne materiały, indywidualne ogrody i najwyższy standard wykończenia w trzech wariantach do wyboru."}],"editable":true,"label":"Cztery filary (ikony: facade, pin, spa, key, shield, golf …)","type":"table"}}},{"id":"features","hashId":"udogodnienia","component":"Features","type":"section","label":"Udogodnienia","fields":{"eyebrow":{"value":"Udogodnienia","editable":true,"label":"Nadtytuł","type":"string"},"header":{"value":"Wszystko, czego oczekuje","editable":true,"label":"Nagłówek","type":"string"},"accent":{"value":"najbardziej wymagający gość","editable":true,"label":"Akcent (kursywa)","type":"string"},"text":{"value":"Osiem rozwiązań, które definiują codzienność w Fox Hills Residences — od pola golfowego za ogrodem po wieczorną iluminację elewacji.","editable":true,"label":"Opis","type":"string"},"bgImage":{"value":"/investments/foxhills/gallery/ogrod-i-pole-golfowe.webp","editable":true,"label":"Zdjęcie w tle","type":"asset"},"items":{"value":[{"icon":"golf","title":"Pole golfowe u progu domu","text":"Fairwaye zaczynają się tuż za ogrodem. Poranna runda lub spacer przy zachodzie słońca — bez wsiadania do samochodu."},{"icon":"forest","title":"Las sosnowy i jezioro","text":"Otulające rezydencje sosny i tafla wody tworzą naturalną scenografię, która zmienia się wraz z porami dnia i roku."},{"icon":"glass","title":"Panoramiczne przeszklenia","text":"Wysokie, szklane ściany wpuszczają do wnętrz światło i krajobraz, zacierając granicę między domem a ogrodem."},{"icon":"spa","title":"Taras z jacuzzi","text":"Przestronne drewniane tarasy z jadalnią, strefą lounge i jacuzzi — gotowe na całoroczny wypoczynek."},{"icon":"garden","title":"Prywatny ogród","text":"Projektowana zieleń, kamienie i formowane drzewa w stylu japońskim oraz trawnik przechodzący płynnie w pole golfowe."},{"icon":"garage","title":"Garaż z drewnianymi lamelami","text":"Garaż zintegrowany z bryłą budynku, wykończony ciepłym drewnem i subtelnym oświetleniem LED — jak galeria dla samochodu."},{"icon":"facade","title":"Architektura z charakterem","text":"Ciemna, matowa elewacja zestawiona z ciepłym drewnem. Prosta bryła z dwuspadowym dachem i dachami-tarasami."},{"icon":"light","title":"Iluminacja i nastrój","text":"Starannie zaprojektowane oświetlenie elewacji, ścieżek i ogrodu — wieczorem rezydencja zyskuje zupełnie nowy charakter."}],"editable":true,"label":"Udogodnienia (ikony: golf, forest, glass, spa, garden, garage, facade, light, shield, water, key, city)","type":"table"}}},{"id":"apartments","hashId":"apartamenty","component":"Apartments","type":"section","label":"Dostępne mieszkania","fields":{"eyebrow":{"value":"Dostępne mieszkania","editable":true,"label":"Nadtytuł","type":"string"},"header":{"valu