tatus":"Sprzedany","price":"Cena na zapytanie","link":"","image":""},{"unit":"F/2","building":"F","floor":"Piętro","rooms":"4","area":"191.3","extras":"Taras 70 m² · Garaż 1 stan.","status":"Dostępny","price":"Cena na zapytanie","link":"","image":""}],"editable":true,"label":"Lista lokali (status: Dostępny / Rezerwacja / Sprzedany; link = adres karty lokalu PDF) — DANE PRZYKŁADOWE, UZUPEŁNIJ","type":"table"},"listHeader":{"value":"Lista lokali","editable":true,"label":"Nadtytuł listy","type":"string"},"prospectusLabel":{"value":"Pobierz prospekt informacyjny","editable":true,"label":"Przycisk prospektu — etykieta","type":"string"},"prospectusUrl":{"value":"","editable":true,"label":"Prospekt informacyjny (adres PDF; puste = przycisk „Poproś o prospekt”)","type":"string"},"prospectusRequestLabel":{"value":"Poproś o prospekt informacyjny","editable":true,"label":"Przycisk prospektu — etykieta, gdy brak pliku","type":"string"},"disclaimer":{"value":"Wizualizacje mają charakter poglądowy i nie stanowią oferty w rozumieniu art. 66 Kodeksu cywilnego. Ceny oraz dostępność lokali ustalane są indywidualnie — skontaktuj się z doradcą KGD.","editable":true,"label":"Zastrzeżenie","type":"string"}}},{"id":"standards","hashId":"standard","component":"Standards","type":"section","label":"Standard wykończenia","fields":{"eyebrow":{"value":"Standard wykończenia","editable":true,"label":"Nadtytuł","type":"string"},"header":{"value":"Trzy sposoby na","editable":true,"label":"Nagłówek","type":"string"},"accent":{"value":"idealne wnętrze","editable":true,"label":"Akcent (kursywa)","type":"string"},"text":{"value":"Do wyboru trzy pakiety wykończenia — od eleganckiej klasyki po w pełni indywidualny projekt. Każdy powstaje we współpracy z architektami KGD, w ramach usługi wykończenia pod klucz.","editable":true,"label":"Opis","type":"string"},"standards":{"value":[{"name":"Classic","tagline":"Elegancka klasyka","text":"Spokojna, ponadczasowa paleta i sprawdzone materiały — gotowe wnętrze, w którym wystarczy zamieszkać.","floors":"Parkiet dębowy w strefach dziennych, wielkoformatowy gres w łazienkach i na tarasie, ściany malowane w stonowanej palecie.","bathrooms":"Armatura w czarnym macie, prysznice walk-in, ceramika podwieszana, lustra z podświetleniem LED.","kitchen":"Zabudowa kuchenna z frontami w fornirze dębowym, blaty ze spieku kwarcowego, garderoby z oświetleniem.","joinery":"Drzwi wewnętrzne w ukrytej ościeżnicy, okna i przeszklenia z pakietami trzyszybowymi.","installations":"Ogrzewanie podłogowe, rekuperacja, przygotowanie pod klimatyzację i system inteligentnego domu.","palette":"Dąb naturalny:#B58B5A|Grafit:#2B2D2C|Kość słoniowa:#E9E1D0","image":"/investments/foxhills/gallery/detale-fasada-1.webp","pdfUrl":""},{"name":"Prestige","tagline":"Szlachetne materiały","text":"Naturalny kamień, forniry z szlachetnych gatunków drewna i dopracowane oświetlenie — wnętrze o charakterze hotelu premium.","floors":"Szeroka deska dębowa lakierowana matowo, kamień naturalny (trawertyn, marmur) w strefie wejścia i łazienkach, panele ścienne z drewna.","bathrooms":"Umywalki z kamienia, baterie podtynkowe, wanny wolnostojące, podgrzewane podłogi.","kitchen":"Kuchnia na wymiar z wyspą, fronty w fornirze i lakierze matowym, zabudowane AGD klasy premium.","joinery":"Drzwi na wysokość pomieszczenia, w tym przesuwne, wykończone fornirem; szklane ściany w ciemnych ramach aluminiowych.","installations":"Inteligentny dom ze scenami świetlnymi, klimatyzacja kanałowa, oświetlenie akcentowe LED w całym domu.","palette":"Trawertyn:#CDBA98|Orzech:#5A3F2B|Czarny mat:#141414","image":"/investments/foxhills/gallery/detale-oswietlenie-1.webp","pdfUrl":""},{"name":"Signature","tagline":"W pełni na miarę","text":"Wnętrze projektowane od zera razem z architektem — indywidualne materiały, meble na wymiar i wyposażenie dopasowane do Twojego stylu życia.","floors":"Dobór materiałów podłogowych i ściennych z pełnej oferty — kamień, drewno, mikrocement, tapety jedwabne.","bathrooms":"Domowe spa: sauna, strefa mokra z oświetleniem nastrojowym, indywidualnie projektowane okładziny.","kitchen":"Kuchnia i garderoba projektowane w pracowni; sprzęt AGD dobrany wspólnie z Tobą.","joinery":"Stolarka otworowa i meblowa na wymiar, drzwi w niestandardowych rozmiarach.","installations":"Kompleksowa automatyka, multiroom, kino domowe oraz rozwiązania dobrane do Twoich potrzeb.","palette":"Mikrocement:#8D8A83|Brąz złoty:#B08A4A|Szmaragd:#1E3B2E","image":"/investments/foxhills/gallery/detale-oswietlenie-2.webp","pdfUrl":""}],"editable":true,"label":"Standardy wykończenia (palette: „Nazwa:#kolor” rozdzielone znakiem |; pdfUrl = zestawienie do pobrania) — TREŚĆ DO AKCEPTACJI","type":"table"},"labels":{"value":{"floors":"Podłogi i ściany","bathrooms":"Łazienki","kitchen":"Kuchnia i garderoba","joinery":"Stolarka i drzwi","installations":"Instalacje i komfort","palette":"Paleta materiałów"},"editable":true,"label":"Nazwy obszarów wykończenia","type":"table"},"downloadLabel":{"value":"Pobierz zestawienie standardu","editable":true,"label":"Przycisk pobrania — etykieta","type":"string"},"requestLabel":{"value":"Poproś o zestawienie standardu","editable":true,"label":"Przycisk, gdy brak pliku PDF — etykieta","type":"string"},"note":{"value":"Zestawienia materiałowe mają charakter przykładowy. Ostateczny zakres określa umowa i dokumentacja projektowa.","editable":true,"label":"Uwaga pod przyciskiem","type":"string"}}},{"id":"gallery","hashId":"galeria","component":"Gallery","type":"section","label":"Galeria","fields":{"eyebrow":{"value":"Galeria","editable":true,"label":"Nadtytuł","type":"string"},"header":{"value":"Zobacz Fox Hills","editable":true,"label":"Nagłówek","type":"string"},"accent":{"value":"w pełnym blasku","editable":true,"label":"Akcent (kursywa)","type":"string"},"text":{"value":"Wizualizacje inwestycji o każdej porze dnia — od złotej godziny nad polem golfowym po wieczorną iluminację ogrodu.","editable":true,"label":"Opis","type":"string"},"allLabel